<div class="modal-overlay" id="delete-modal"><div class="modal-box"><div class="modal-icon">🗑️</div><div class="modal-title">Xác nhận xóa</div><div class="modal-desc" id="delete-modal-desc">Bạn có chắc chắn muốn xóa mục này không?</div><div class="modal-actions"><button type="button" class="btn-admin btn-admin-ghost" onclick="closeDeleteModal()">Hủy bỏ</button><form id="delete-form" method="POST" style="display:inline">@csrf @method('DELETE')<button type="submit" class="btn-admin btn-admin-danger">Xóa ngay</button></form></div></div></div>
<script>
  const flash=document.getElementById('flash-msg');if(flash)setTimeout(()=>flash.style.opacity='0',4000);
  function confirmDelete(action,itemName){const modal=document.getElementById('delete-modal');document.getElementById('delete-form').action=action;document.getElementById('delete-modal-desc').textContent=itemName?`Bạn có chắc muốn xóa "${itemName}"?`:'Bạn có chắc chắn muốn xóa mục này không?';modal.classList.add('show')}
  function openDeleteModal(action,itemName){confirmDelete(action,itemName)} function closeDeleteModal(){document.getElementById('delete-modal').classList.remove('show')}
  document.getElementById('delete-modal')?.addEventListener('click',e=>{if(e.target===e.currentTarget)closeDeleteModal()});
  const sidebar=document.getElementById('admin-sidebar'),overlay=document.getElementById('admin-overlay');function closeSidebar(){sidebar?.classList.remove('open');overlay?.classList.remove('show')}document.getElementById('mobile-menu-btn')?.addEventListener('click',()=>{sidebar?.classList.toggle('open');overlay?.classList.toggle('show')});overlay?.addEventListener('click',closeSidebar);window.addEventListener('resize',()=>{if(window.innerWidth>860)closeSidebar()});
</script>
